-- Market-channel releases on the SDKWork storefront channel.
SELECT
    'mrel-' || r.id,
    r.tenant_id,
    r.organization_id,
    l.app_id,
    r.listing_id,
    r.id,
    'mch-sdkwork-pc',
    'MR-' || UPPER(REPLACE(r.id, '-', '')),
    l.app_key,
    r.version_code,
    'production',
    'published',
    100,
    '["CN", "US"]',
    'https://appstore.sdkwork.local/apps/' || l.listing_slug,
    '{"syncState": "seeded"}',
    r.submitted_at,
    r.approved_at,
    r.published_at,
    NULL,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP
FROM appstore_release r
JOIN appstore_listing l
  ON l.id = r.listing_id
 AND l.tenant_id = r.tenant_id
WHERE r.tenant_id = '100001'
  AND r.release_status = 'published'
  AND r.id IN (
